"""Vocabulary example sentences generated by Claude, stored per user and entry."""

from __future__ import annotations

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from app.api.deps import DAILY_QUOTAS, enforce_quota, get_current_user
from app.db.session import get_db
from app.models import User
from app.schemas import ExampleGenerateRequest, ExampleGenerateResponse, WordExampleItem
from app.services import example_service, expression_service, llm_service


QUOTA_KIND = "example_generation"

router = APIRouter(prefix="/examples", tags=["examples"])


@router.get(
    "",
    response_model=list[WordExampleItem],
    summary="List the authenticated user's saved examples for one entry, newest first.",
)
def get_examples(
    entry_id: int = Query(..., ge=1),
    db: Session = Depends(get_db),
    user: User = Depends(get_current_user),
) -> list[WordExampleItem]:
    rows = example_service.list_examples(db, user_id=user.id, entry_id=entry_id)
    return [WordExampleItem.model_validate(r) for r in rows]


@router.post(
    "",
    response_model=ExampleGenerateResponse,
    status_code=status.HTTP_201_CREATED,
    summary="Generate a new example sentence for an entry via Claude and save it.",
)
def post_generate_example(
    payload: ExampleGenerateRequest,
    db: Session = Depends(get_db),
    user: User = Depends(enforce_quota(QUOTA_KIND)),
) -> ExampleGenerateResponse:
    found = example_service.get_entry_with_level(db, payload.entry_id)
    if found is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Mot introuvable.")
    entry, level = found

    if not llm_service.is_configured():
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE,
            detail="API Anthropic non configurée côté serveur.",
        )

    previous = example_service.list_examples(db, user_id=user.id, entry_id=entry.id, limit=10)
    try:
        example, usage = llm_service.generate_example(
            hanzi=entry.hanzi,
            pinyin=entry.pinyin,
            translation=entry.translation,
            level=level,
            avoid_sentences=[p.sentence for p in previous],
        )
    except llm_service.LLMNotConfiguredError as exc:
        raise HTTPException(
            status_code=status.HTTP_503_SERVICE_UNAVAILABLE, detail=str(exc)
        ) from exc
    except RuntimeError as exc:
        raise HTTPException(status_code=status.HTTP_502_BAD_GATEWAY, detail=str(exc)) from exc

    row = example_service.save_example(
        db,
        user_id=user.id,
        entry_id=entry.id,
        hsk_level=level,
        example=example,
        tokens_input=usage.input_tokens,
        tokens_output=usage.output_tokens,
        model_id=llm_service.get_model_id(),
    )
    updated = expression_service.increment_daily_usage(
        db,
        user_id=user.id,
        kind=QUOTA_KIND,
        count_delta=1,
        tokens_input_delta=usage.input_tokens,
        tokens_output_delta=usage.output_tokens,
    )

    return ExampleGenerateResponse(
        example=WordExampleItem.model_validate(row),
        quota_remaining=max(0, DAILY_QUOTAS[QUOTA_KIND] - int(updated.count or 0)),
    )
